E CS_LONGDATE, "BPLId" INTEGER CS_INT, "DPPStatus" NVARCHAR(1) DEFAULT 'N', "EncryptIV" NVARCHAR(100), PRIMARY KEY ("DocEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
